// GENERATED by tools/build_gate_crate.py — do not edit by hand.
//
// Computes the crate identity that `FRONTIER_ID` and `ADMISSION_SURFACE_ID`
// end in (issue #1768): the first 16 hex digits of a sha256 over this crate's
// `Cargo.toml`, `build.rs` and `src/**/*.rs`, sorted by path, each fed as
// `<relpath> NUL <bytes> NUL`. The id is computed rather than committed so no
// generated file carries a digest every self-host change rewrites, and it names
// the exact bytes compiled. `tools/build_gate_crate.py::crate_identity` is the
// same computation; `tests/test_gate_crate_admit.py` holds the two equal.
//
// No dependency: a small sha256, because a build dependency would be one more
// crate every consumer fetches to learn a name.

use std::fs;
use std::path::{Path, PathBuf};

fn collect(root: &Path, dir: &Path, out: &mut Vec<String>) {
    let mut entries: Vec<PathBuf> = fs::read_dir(dir)
        .expect("read src/")
        .map(|e| e.expect("dir entry").path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            collect(root, &path, out);
        } else if path.extension().map_or(false, |e| e == "rs") {
            let rel = path.strip_prefix(root).expect("under the crate root");
            let parts: Vec<String> = rel
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect();
            out.push(parts.join("/"));
        }
    }
}

